const now = new Date();
const bogotaDate = (d) => d.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const items = [];
for (let offset = -1; offset <= 3; offset++) {
  const d = new Date(now);
  d.setDate(d.getDate() + offset);
  items.push({ json: { date: bogotaDate(d), label: offset === 0 ? 'today' : 'day_' + offset } });
}
return items;

const items = $('Get Football Live').all();
const seen = new Set();
const matches = [];
let source = 'unknown';
for (const item of items) {
  const data = item.json || {};
  if (data.source) source = data.source;
  const itemMatches = data.matches || data.response?.matches || [];
  for (const match of itemMatches) {
    if (!match || !match.id || seen.has(match.id)) continue;
    seen.add(match.id);
    matches.push(match);
  }
}
return [{ json: { matches, count: matches.length, source } }];

// Merge football and tennis data using explicit node references
let query = {};
try { query = $('Webhook Trigger').first().json.query || {}; } catch (e) { query = {}; }
const requestedSport = (query.sport || '').toLowerCase();
const includeFootball = !requestedSport || requestedSport === 'football';
const includeTennis = !requestedSport || requestedSport === 'tennis';

let footballData = {};
let footballOddsByMatchId = {};
let footballH2hByMatchId = {};
if (includeFootball) {
  try {
    const rawFootball = $('Merge Football API Responses').first().json;
    footballData = (rawFootball && typeof rawFootball === 'object') ? rawFootball : {};
    const rawFbOdds = $('Merge Football Odds').first().json;
    footballOddsByMatchId = (rawFbOdds && rawFbOdds.oddsByMatchId) ? rawFbOdds.oddsByMatchId : {};
  } catch(e) { footballData = {}; }
}
let tennisEvents = [];
let oddsByMatchId = {};
let tennisH2hByMatchId = {};
if (includeTennis) {
  try {
    tennisEvents = $('Extract Tennis Events').all().map(item => item.json || {}).filter(ev => ev && ev.eventId);
    const rawOdds = $('Merge Tennis Odds').first().json;
    oddsByMatchId = (rawOdds && rawOdds.oddsByMatchId) ? rawOdds.oddsByMatchId : {};
    const rawTennisH2h = $('Merge Tennis H2H').first().json;
    tennisH2hByMatchId = (rawTennisH2h && rawTennisH2h.h2hByMatchId) ? rawTennisH2h.h2hByMatchId : {};
  } catch(e) { tennisEvents = []; }
}

const now = new Date();
const dateStr = now.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const yesterday = new Date(now.getTime() - 86400000);
const yesterdayStr = yesterday.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });

// --- Football importance tiers ---
// Lower number = more important. IDs are from free-api-live-football-data.
const footballLeagueNames = {
  894789: 'FIFA World Cup',
};
const footballLeagueTiers = {
  894789: 1, // FIFA World Cup 2026
};
const topCountries = new Set([
  'argentina','australia','belgium','brazil','canada','chile','colombia','costa rica','croatia',
  'denmark','ecuador','egypt','england','france','germany','ghana','iran','italy','ivory coast',
  'japan','korea','mexico','morocco','netherlands','nigeria','norway','paraguay','peru','poland',
  'portugal','saudi arabia','senegal','serbia','spain','switzerland','tunisia','ukraine','uruguay',
  'usa','wales','south africa','algeria','cameroon','scotland'
]);

function getFootballMatchTier(match) {
  const leagueId = Number(match.leagueId);
  if (footballLeagueTiers[leagueId] !== undefined) {
    return footballLeagueTiers[leagueId];
  }
  const home = (match.home?.name || match.home?.longName || '').toLowerCase();
  const away = (match.away?.name || match.away?.longName || '').toLowerCase();
  if (topCountries.has(home) && topCountries.has(away)) return 2;
  return 5;
}

// Format football matches: keep only today's matches, sort by importance, cap at 25
const footballMatches = [];
const footballMatchesRaw = footballData.matches || [];
const sortedFootball = footballMatchesRaw
  .filter(m => {
    const utcTime = m.status?.utcTime;
    if (!utcTime) return true;
    const d = new Date(utcTime);
    const localDate = d.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
    return localDate === dateStr || localDate === yesterdayStr;
  })
  .sort((a, b) => {
    const tierDiff = getFootballMatchTier(a) - getFootballMatchTier(b);
    if (tierDiff !== 0) return tierDiff;
    return (a.status?.utcTime || '').localeCompare(b.status?.utcTime || '');
  });

for (const match of sortedFootball.slice(0, 15)) {
  const status = match.status || {};
  const utcTime = status.utcTime;
  const matchDate = utcTime ? new Date(utcTime) : new Date();
  const eventDate = matchDate.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
  const eventTime = matchDate.toLocaleTimeString('en-GB', { timeZone: 'America/Bogota', hour: '2-digit', minute: '2-digit' });
  const finished = status.finished || (status.reason?.short === 'FT');
  const started = status.started;
  let matchStatus = 'SCHEDULED';
  if (finished) matchStatus = 'FINISHED';
  else if (started) matchStatus = 'LIVE';
  else if (status.cancelled) matchStatus = 'CANCELLED';

  const fbMatchId = `FOOTBALL-${match.id}`;
  const fbOdds = footballOddsByMatchId[fbMatchId] || {};
  const fbH2h = footballH2hByMatchId[fbMatchId] || null;
  const leagueId = Number(match.leagueId);
  footballMatches.push({
    matchId: fbMatchId,
    leagueTier: getFootballMatchTier(match),
    homeTeam: match.home?.name || match.home?.longName || 'Unknown',
    awayTeam: match.away?.name || match.away?.longName || 'Unknown',
    league: footballLeagueNames[leagueId] || String(leagueId),
    eventDate: eventDate,
    eventTime: eventTime,
    homePosition: 0,
    awayPosition: 0,
    homeForm: 'N/A',
    awayForm: 'N/A',
    homeXg: 0,
    awayXg: 0,
    homeCorners: 0,
    awayCorners: 0,
    homeOdds: fbOdds.homeOdds || null,
    drawOdds: fbOdds.drawOdds || null,
    awayOdds: fbOdds.awayOdds || null,
    headToHead: fbH2h,
    eventId: match.id,
    homeScore: match.home?.score || 0,
    awayScore: match.away?.score || 0,
    status: matchStatus
  });
}

// --- External consensus: ClubElo fixture predictions (football, shadow mode) ---
function normTeamName(name) {
  return (name || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}
const CLUB_TOKENS = new Set(['fc','sc','cf','ac','afc','cd','ud','ec','rc','ca','club','de','fk','sk','bk','if','sv','ssc','as','us','rcd','se','bc']);
function teamTokens(name) {
  return normTeamName(name).split(' ').filter(t => t && !CLUB_TOKENS.has(t));
}
function teamsMatch(a, b) {
  const ta = teamTokens(a);
  const tb = teamTokens(b);
  if (!ta.length || !tb.length) return false;
  const tokenEq = (x, y) => x === y || (x.length >= 5 && y.length >= 5 && (x.startsWith(y) || y.startsWith(x)));
  const inter = ta.filter(x => tb.some(y => tokenEq(x, y))).length;
  const union = new Set(ta.concat(tb)).size;
  if (inter / union >= 0.5) return true;
  const shorter = ta.length <= tb.length ? ta : tb;
  const longer = ta.length <= tb.length ? tb : ta;
  return shorter.every(x => longer.some(y => tokenEq(x, y)));
}
function parseClubElo(html) {
  const fixtures = [];
  if (!html || typeof html !== 'string') return fixtures;
  const fIdx = html.indexOf('<h2><a href="Fixtures">');
  const rIdx = html.indexOf('<h2><a href="Results">');
  let block = html;
  if (fIdx >= 0 && rIdx > fIdx) {
    block = html.slice(fIdx, rIdx);
  } else if (rIdx > 0) {
    block = html.slice(0, rIdx);
  }
  const textRe = /<text\b[^>]*>([\s\S]*?)<\/text>/g;
  const rows = {};
  let m;
  while ((m = textRe.exec(block)) !== null) {
    const tag = m[0];
    const xm = tag.match(/\bx="([\d.\-]+)"/);
    const ym = tag.match(/\by="([\d.\-]+)"/);
    if (!xm || !ym) continue;
    const x = parseFloat(xm[1]);
    const y = parseFloat(ym[1]);
    const content = m[1].replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').trim();
    if (!content) continue;
    const key = String(y);
    (rows[key] = rows[key] || []).push({ x: x, content: content });
  }
  for (const key of Object.keys(rows)) {
    const cells = rows[key];
    const homes = cells.filter(c => Math.abs(c.x - 20) < 6);
    const aways = cells.filter(c => Math.abs(c.x - 235) < 6);
    const hps = cells.filter(c => Math.abs(c.x - 534) < 8);
    const aps = cells.filter(c => Math.abs(c.x - 578) < 8);
    const hes = cells.filter(c => Math.abs(c.x - 180) < 8);
    const aes = cells.filter(c => Math.abs(c.x - 395) < 8);
    const n = Math.min(homes.length, aways.length, hps.length, aps.length);
    for (let i = 0; i < n; i++) {
      const homePct = parseFloat(hps[i].content);
      const awayPct = parseFloat(aps[i].content);
      if (isNaN(homePct) || isNaN(awayPct)) continue;
      fixtures.push({ home: homes[i].content, away: aways[i].content, homeWinPct: homePct, awayWinPct: awayPct, homeElo: hes[i] ? parseFloat(hes[i].content) : null, awayElo: aes[i] ? parseFloat(aes[i].content) : null });
    }
  }
  return fixtures;
}
let clubeloFixtures = [];
try {
  const clubeloRaw = $('Get ClubElo').first().json;
  clubeloFixtures = parseClubElo(clubeloRaw && clubeloRaw.data ? clubeloRaw.data : '');
} catch (e) { clubeloFixtures = []; }
for (const fm of footballMatches) {
  const hit = clubeloFixtures.find(f => teamsMatch(f.home, fm.homeTeam) && teamsMatch(f.away, fm.awayTeam));
  if (hit) {
    fm.expertConsensus = { source: 'clubelo', homeTeam: fm.homeTeam, awayTeam: fm.awayTeam, homeWinPct: hit.homeWinPct, awayWinPct: hit.awayWinPct, homeElo: hit.homeElo, awayElo: hit.awayElo };
  }
}

// Format tennis matches (from Extract Tennis Events: ATP + WTA parsed)
const tennisMatches = [];
for (const event of tennisEvents.slice(0, 50)) {
  const matchId = event.matchId || `TENNIS-${event.eventId}`;
  const odds = oddsByMatchId[matchId] || {};
  const surface = event.surface || 'hard';
  const eventDate = event.eventDate || dateStr;
  const eventTime = event.eventTime || null;

  tennisMatches.push({
    matchId: matchId,
    player1: event.player1 || 'Unknown',
    player2: event.player2 || 'Unknown',
    tournament: event.tournament || 'Unknown',
    eventDate: eventDate,
    eventTime: eventTime,
    rankingPlayer1: event.rankingPlayer1 || 0,
    rankingPlayer2: event.rankingPlayer2 || 0,
    surface: surface,
    groundType: surface,
    tournamentTier: event.tournamentTier || 0,
    countryPlayer1: event.countryPlayer1 || null,
    countryPlayer2: event.countryPlayer2 || null,
    formPlayer1: 'N/A',
    formPlayer2: 'N/A',
    acesAvgPlayer1: 0,
    acesAvgPlayer2: 0,
    oddsPlayer1: odds.oddsPlayer1 || event.oddsPlayer1 || null,
    oddsPlayer2: odds.oddsPlayer2 || event.oddsPlayer2 || null,
    h2h: tennisH2hByMatchId[matchId] || 'N/A',
    eventId: event.eventId,
    status: event.status || 'Not started',
    seed1: event.seed1 || null,
    seed2: event.seed2 || null
  });
}

const output = {
  generatedAt: now.toISOString(),
  source: 'live_api',
  tennis: tennisMatches,
  football: footballMatches,
  requestedSport: requestedSport || 'all'
};

return [{ json: output }];

const data = $('Merge & Format Data').first().json;
const footballCount = data.football?.length || 0;
const tennisCount = data.tennis?.length || 0;
const count = footballCount + tennisCount;
const dbResult = $input.first().json || {};
const inserted = dbResult.inserted || 0;
const errors = dbResult.errors || [];
const telegramMessage = `<b>BrainBets - Datos Recolectados</b>\n\nTotal partidos: ${count}\n- Futbol: ${footballCount}\n- Tenis: ${tennisCount}\nInsertados en DB: ${inserted}\nErrores: ${errors.length}`;
return [{
  json: {
    telegramMessage: telegramMessage,
    dbResult: dbResult
  }
}];

// Parse api-tennis.com fixtures (ATP singles main draw only, event_type_key=265)
// Single source: fixtures + odds + standings share the same event_key/player names.
const fixturesData = $('Get Tennis Live').first().json || {};
let oddsData = {}; try { oddsData = $('Get Tennis Odds').first().json || {}; } catch(e) { oddsData = {}; }
let standingsData = {}; try { standingsData = $('Get Tennis Rankings').first().json || {}; } catch(e) { standingsData = {}; }

const allMatches = Array.isArray(fixturesData.result) ? fixturesData.result : [];
const oddsByKey = (oddsData.result && typeof oddsData.result === 'object' && !Array.isArray(oddsData.result)) ? oddsData.result : {};

// --- Rankings lookup (get_standings ATP returns full names: 'Jannik Sinner') ---
function normName(name) {
  return (name || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
}
const rankByName = {};
for (const r of (Array.isArray(standingsData.result) ? standingsData.result : [])) {
  const full = normName(r.player || '');
  const place = parseInt(r.place);
  if (full && place && !(full in rankByName)) rankByName[full] = place;
}
function lookupRank(playerName) {
  const n = normName(playerName);
  if (!n) return null;
  if (rankByName[n] !== undefined) return rankByName[n];
  const parts = n.split(' ').filter(Boolean);
  if (parts.length < 2) return null;
  // Fallback 1: surname + first initial ('C. Alcaraz' vs 'Carlos Alcaraz')
  const surname = parts[parts.length - 1];
  const firstInitial = parts[0][0];
  for (const full in rankByName) {
    const fp = full.split(' ').filter(Boolean);
    if (fp.length < 2) continue;
    if (fp[fp.length - 1] === surname && fp[0][0] === firstInitial) return rankByName[full];
  }
  // Fallback 2: token-set match for scrambled standings names ('Martin Etcheverry Tomas')
  const initials = parts.filter(p => p.length === 1);
  const nameTokens = parts.filter(p => p.length > 1);
  if (!nameTokens.length) return null;
  for (const full in rankByName) {
    const fp = full.split(' ').filter(Boolean);
    if (fp.length < 2) continue;
    const tokenSet = new Set(fp);
    if (!nameTokens.every(t => tokenSet.has(t))) continue;
    const fullInitials = new Set(fp.map(t => t[0]));
    if (initials.every(i => fullInitials.has(i))) return rankByName[full];
  }
  return null;
}

// --- Odds: prefer sharp books, fallback to any available ---
const BOOKIE_PRIORITY = ['Pncl', 'bet365', 'Betfair', 'WilliamHill', 'Unibet', 'Marathon', '1xBet', '10Bet', 'Bwin', 'bwin', 'Betsson'];
function pickOdd(selection) {
  if (!selection || typeof selection !== 'object') return null;
  for (const b of BOOKIE_PRIORITY) {
    if (selection[b] !== undefined) { const v = parseFloat(selection[b]); if (v > 1.0) return v; }
  }
  for (const k of Object.keys(selection)) { const v = parseFloat(selection[k]); if (v > 1.0) return v; }
  return null;
}

// --- Surface heuristic (api-tennis fixtures have no surface field) ---
const GRASS = ['wimbledon', 'halle', 'queen', 'hertogenbosch', 'den bosch', 'stuttgart', 'eastbourne', 'newport', 'mallorca', 'bad homburg', 'berlin', 'newport'];
const CLAY = ['kitzbuhel', 'estoril', 'hamburg', 'bastad', 'gstaad', 'umag', 'geneva', 'lyon', 'bucharest', 'marrakech', 'houston', 'bogota', 'santiago', 'buenos aires', 'rio de janeiro', 'rio open', 'roland', 'french open', 'monte-carlo', 'monte carlo', 'madrid', 'rome', 'roma', 'barcelona', 'belgrade', 'istanbul', 'parma', 'rabat', 'palermo', 'budapest'];
function guessSurface(tName) {
  const t = (tName || '').toLowerCase();
  for (const k of GRASS) { if (t.includes(k)) return 'grass'; }
  for (const k of CLAY) { if (t.includes(k)) return 'clay'; }
  return 'hard';
}

// --- Tournament tier (feed is already ATP singles only) ---
const SLAMS = ['australian open', 'roland garros', 'french open', 'wimbledon', 'us open'];
const MASTERS = ['indian wells', 'miami', 'monte-carlo', 'monte carlo', 'madrid', 'rome', 'roma', 'canada', 'toronto', 'montreal', 'cincinnati', 'shanghai', 'paris'];
const ATP500 = ['rotterdam', 'dallas', 'doha', 'rio', 'acapulco', 'dubai', 'barcelona', 'halle', 'queen', 'hamburg', 'washington', 'beijing', 'tokyo', 'vienna', 'basel', 'munich'];
function guessTier(tName, roundName) {
  const t = (tName || '').toLowerCase();
  const r = (roundName || '').toLowerCase();
  for (const k of SLAMS) { if (t.includes(k)) return 100; }
  for (const k of MASTERS) { if (t.includes(k)) return 80; }
  for (const k of ATP500) { if (t.includes(k)) return 60; }
  if (r.includes('olympics') || t.includes('atp finals') || t.includes('next gen') || t.includes('davis') || t.includes('united cup')) return 90;
  return 40; // ATP 250
}

function mapStatus(m) {
  const s = (m.event_status || '').toLowerCase();
  if (m.event_live === '1') return 'LIVE';
  if (s === 'finished' || s === 'ended') return 'FINISHED';
  if (s === 'retired' || s === 'walkover' || s === 'cancelled') return 'CANCELLED';
  if (s === '' || s === 'not started') return 'SCHEDULED';
  return 'LIVE'; // 'Set 1', 'Set 2', ...
}

const items = [];
for (const m of allMatches.slice(0, 100)) {
  // Main draw only: skip qualification rounds
  if (String(m.event_qualification) === 'True') continue;

  const mkts = oddsByKey[String(m.event_key)] || {};
  const homeAway = mkts['Home/Away'] || {};
  const surface = guessSurface(m.tournament_name);

  items.push({ json: {
    eventId: m.event_key,
    matchId: 'TENNIS-' + m.event_key,
    player1: m.event_first_player || 'Unknown',
    player2: m.event_second_player || 'Unknown',
    eventDate: m.event_date || null,  // Bogotá local date (timezone param)
    eventTime: m.event_time || null,  // Bogotá local time 'HH:MM'
    rankingPlayer1: lookupRank(m.event_first_player),
    rankingPlayer2: lookupRank(m.event_second_player),
    surface: surface,
    groundType: surface,
    tournamentTier: guessTier(m.tournament_name, m.tournament_round),
    countryPlayer1: null,
    countryPlayer2: null,
    status: mapStatus(m),
    seed1: null,
    seed2: null,
    roundName: m.tournament_round || null,
    tournament: m.tournament_name || null,
    oddsPlayer1: pickOdd(homeAway.Home),
    oddsPlayer2: pickOdd(homeAway.Away),
    totalSetsLine: null,
    overTotalOdds: null,
    underTotalOdds: null,
    handicap1: null,
    handicap1Odds: null,
    handicap2: null,
    handicap2Odds: null
  }});
}
// Never return zero items: an empty output silently kills the rest of the serial chain (football DB write, notification)
if (items.length === 0) {
  items.push({ json: { eventId: '', matchId: '', noMatches: true } });
}
return items;

// Odds are now included in the new API fixtures response
// Extract them directly from Extract Tennis Events output
const eventItems = $('Extract Tennis Events').all();
const oddsByMatchId = {};

for (const item of eventItems) {
  const ev = item.json || {};
  if (!ev.eventId) continue;
  const matchId = ev.matchId || `TENNIS-${ev.eventId}`;

  // Odds are already extracted in Extract Tennis Events
  const o1 = ev.oddsPlayer1;
  const o2 = ev.oddsPlayer2;

  if (o1 && o2 && o1 > 1.0 && o2 > 1.0) {
    oddsByMatchId[matchId] = {
      oddsPlayer1: Number(o1.toFixed(3)),
      oddsPlayer2: Number(o2.toFixed(3)),
      totalSetsLine: ev.totalSetsLine || null,
      overTotalOdds: ev.overTotalOdds || null,
      underTotalOdds: ev.underTotalOdds || null,
      handicap1: ev.handicap1 || null,
      handicap1Odds: ev.handicap1Odds || null,
      handicap2: ev.handicap2 || null,
      handicap2Odds: ev.handicap2Odds || null
    };
  }
}
return [{ json: { oddsByMatchId } }];

const footballData = $('Merge Football API Responses').first().json || {};
const matches = footballData.matches || [];
const items = [];
for (const match of matches.slice(0, 45)) {
  items.push({ json: { eventId: match.id, matchId: `FOOTBALL-${match.id}` } });
}
// Never return zero items: an empty output silently kills the rest of the serial chain (tennis, DB write, notification)
if (items.length === 0) {
  items.push({ json: { eventId: '', matchId: '', noMatches: true } });
}
return items;

const oddsItems = $('Get Football Odds').all();
const eventItems = $('Extract Football Events').all();
const oddsByMatchId = {};

function findOdds(json) {
  if (!json || typeof json !== 'object') return null;
  if (json.homeOdds !== undefined && json.drawOdds !== undefined && json.awayOdds !== undefined) {
    return { homeOdds: json.homeOdds, drawOdds: json.drawOdds, awayOdds: json.awayOdds };
  }
  if (json.home_odd !== undefined && json.draw_odd !== undefined && json.away_odd !== undefined) {
    return { homeOdds: json.home_odd, drawOdds: json.draw_odd, awayOdds: json.away_odd };
  }

  const oddsRoot = (json.response && json.response.odds) || json.odds;
  const oddsPayload = (oddsRoot && oddsRoot.odds) || oddsRoot;

  if (oddsPayload && typeof oddsPayload === 'object') {
    const o = oddsPayload;
    if (o['1'] !== undefined && o['X'] !== undefined && o['2'] !== undefined) {
      return { homeOdds: o['1'], drawOdds: o['X'], awayOdds: o['2'] };
    }
    if (o.home !== undefined && o.draw !== undefined && o.away !== undefined) {
      return { homeOdds: o.home, drawOdds: o.draw, awayOdds: o.away };
    }
  }

  function extractFromMarket(market) {
    if (!market || !Array.isArray(market.selections)) return null;
    const home = market.selections.find(x => String(x.name).toLowerCase() === '1');
    const draw = market.selections.find(x => String(x.name).toLowerCase() === 'x');
    const away = market.selections.find(x => String(x.name).toLowerCase() === '2');
    if (home && draw && away) {
      return { homeOdds: home.oddsDecimal, drawOdds: draw.oddsDecimal, awayOdds: away.oddsDecimal };
    }
    return null;
  }

  if (oddsPayload && Array.isArray(oddsPayload.matchfactMarkets)) {
    const m = oddsPayload.matchfactMarkets.find(x => /fulltime|full.time|who.will.win|1x2/i.test(String(x.header || x.headerTranslationKey)));
    const extracted = extractFromMarket(m);
    if (extracted) return extracted;
  }
  if (oddsPayload && Array.isArray(oddsPayload.oddsTabMarkets)) {
    for (const tab of oddsPayload.oddsTabMarkets) {
      const markets = Array.isArray(tab.markets) ? tab.markets : [];
      const m = markets.find(x => /fulltime|full.time|who.will.win|1x2/i.test(String(x.header || x.headerTranslationKey)));
      const extracted = extractFromMarket(m);
      if (extracted) return extracted;
    }
  }

  const markets = Array.isArray(json.markets) ? json.markets : (Array.isArray(oddsPayload && oddsPayload.markets) ? oddsPayload.markets : null);
  if (markets) {
    const m = markets.find(x => /1x2|fulltime|full.time|who.will.win/i.test(String(x.name || x.marketName || x.market || x.header || x.headerTranslationKey)));
    if (m) {
      if (Array.isArray(m.values)) {
        const home = m.values.find(x => String(x.value).toLowerCase() === 'home' || String(x.value) === '1');
        const draw = m.values.find(x => String(x.value).toLowerCase() === 'draw' || String(x.value).toLowerCase() === 'x');
        const away = m.values.find(x => String(x.value).toLowerCase() === 'away' || String(x.value) === '2');
        return { homeOdds: home && home.odd, drawOdds: draw && draw.odd, awayOdds: away && away.odd };
      }
      return extractFromMarket(m);
    }
  }
  return null;
}

for (let i = 0; i < oddsItems.length; i++) {
  const eventId = eventItems[i] && eventItems[i].json.eventId;
  if (!eventId) continue;
  const matchId = 'FOOTBALL-' + eventId;
  const odds = findOdds(oddsItems[i].json);
  if (odds && odds.homeOdds && odds.drawOdds && odds.awayOdds) {
    oddsByMatchId[matchId] = {
      homeOdds: Number(parseFloat(odds.homeOdds).toFixed(3)),
      drawOdds: Number(parseFloat(odds.drawOdds).toFixed(3)),
      awayOdds: Number(parseFloat(odds.awayOdds).toFixed(3)),
    };
  }
}
return [{ json: { oddsByMatchId } }];

const input = $('Merge & Format Data').first().json;
const enriched = $('Enrich Football Stats').first().json || {};
const statsById = (enriched.stats || {});

const football = (input.football || []).map(match => {
  const stats = statsById[match.matchId] || {};
  const apiH2h = match.headToHead;
  const dbH2h = stats.headToHead;
  const headToHead = (apiH2h && apiH2h.matches > 0) ? apiH2h : ((dbH2h && dbH2h.matches > 0) ? dbH2h : null);

  return {
    ...match,
    homePosition: stats.homePosition != null ? stats.homePosition : match.homePosition,
    awayPosition: stats.awayPosition != null ? stats.awayPosition : match.awayPosition,
    homeForm: stats.homeForm || match.homeForm,
    awayForm: stats.awayForm || match.awayForm,
    homeXg: stats.homeXg != null ? stats.homeXg : match.homeXg,
    awayXg: stats.awayXg != null ? stats.awayXg : match.awayXg,
    homeXgAgainst: stats.homeXgAgainst != null ? stats.homeXgAgainst : null,
    awayXgAgainst: stats.awayXgAgainst != null ? stats.awayXgAgainst : null,
    homeCorners: stats.homeCorners != null ? stats.homeCorners : match.homeCorners,
    awayCorners: stats.awayCorners != null ? stats.awayCorners : match.awayCorners,
    headToHead: headToHead,
    homeFormStats: stats.homeFormStats || null,
    awayFormStats: stats.awayFormStats || null,
    leagueStandings: stats.leagueStandings || null,
    statsDataQuality: stats.dataQuality || 'fallback',
  };
});

return [{
  json: {
    generatedAt: input.generatedAt,
    source: input.source,
    tennis: input.tennis || [],
    football: football,
  }
}];

